// PLACEHOLDER — NOT REAL CREDENTIALS.
//
// This file is normally GENERATED by the FlutterFire CLI and should be
// regenerated (not hand-edited) once a Firebase project exists:
//
//   dart pub global activate flutterfire_cli
//   flutterfire configure --project=campus-on-<your-project-id>
//
// That command overwrites this file with the real per-platform options AND
// drops `android/app/google-services.json` + `ios/Runner/GoogleService-Info.plist`.
// Those files hold no server secrets (Firebase app config is public by design);
// access is gated by Firestore security rules (`firestore.rules`), not by hiding
// these ids. Even so, they are per-project config and should come from
// `flutterfire configure`, never be copied from another project.
//
// The values below are obvious placeholders so an accidental
// `--dart-define=USE_FIRESTORE=true` run fails fast at Firebase.initializeApp
// instead of silently pointing at the wrong project.

import 'package:firebase_core/firebase_core.dart' show FirebaseOptions;
import 'package:flutter/foundation.dart'
    show TargetPlatform, defaultTargetPlatform, kIsWeb;

class DefaultFirebaseOptions {
  const DefaultFirebaseOptions._();

  static FirebaseOptions get currentPlatform {
    if (kIsWeb) {
      throw UnsupportedError(
        'Campus-On targets iOS + Android only; web is out of scope for MVP.',
      );
    }
    switch (defaultTargetPlatform) {
      case TargetPlatform.android:
        return android;
      case TargetPlatform.iOS:
        return ios;
      default:
        throw UnsupportedError(
          'No Firebase options for $defaultTargetPlatform. '
          'Run `flutterfire configure` to regenerate this file.',
        );
    }
  }

  static const FirebaseOptions android = FirebaseOptions(
    apiKey: 'REPLACE_VIA_flutterfire_configure',
    appId: 'REPLACE_VIA_flutterfire_configure',
    messagingSenderId: 'REPLACE_VIA_flutterfire_configure',
    projectId: 'campus-on-REPLACE',
    storageBucket: 'campus-on-REPLACE.appspot.com',
  );

  static const FirebaseOptions ios = FirebaseOptions(
    apiKey: 'REPLACE_VIA_flutterfire_configure',
    appId: 'REPLACE_VIA_flutterfire_configure',
    messagingSenderId: 'REPLACE_VIA_flutterfire_configure',
    projectId: 'campus-on-REPLACE',
    storageBucket: 'campus-on-REPLACE.appspot.com',
    iosBundleId: 'com.campuson.app',
  );
}
